/**
 * This browser's device key. The private key is generated by WebCrypto as
 * non-extractable and only ever leaves IndexedDB as an opaque CryptoKey handle;
 * the Host sees the public key and signatures. Encodings match the Host's
 * `apps/host/src/crypto.ts` and are checked against the shared vectors.
 */

/** RFC 4648 base32, lowercase, no padding. */
export const BASE32_ALPHABET = 'abcdefghijklmnopqrstuvwxyz234567'

export function base32(data: Uint8Array): string {
  let output = ''
  let buffer = 0
  let bits = 0
  for (const byte of data) {
    buffer = (buffer << 8) | byte
    bits += 8
    while (bits >= 5) {
      output += BASE32_ALPHABET[(buffer >>> (bits - 5)) & 31]
      bits -= 5
    }
    buffer &= (1 << bits) - 1
  }
  if (bits > 0) output += BASE32_ALPHABET[(buffer << (5 - bits)) & 31]
  return output
}

export function base64url(data: Uint8Array): string {
  let binary = ''
  for (const byte of data) binary += String.fromCharCode(byte)
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

export function base64urlDecode(text: string): Uint8Array {
  const normal = text.replace(/-/g, '+').replace(/_/g, '/')
  const binary = atob(normal + '='.repeat((4 - (normal.length % 4)) % 4))
  return Uint8Array.from(binary, character => character.charCodeAt(0))
}

const utf8 = (text: string) => new TextEncoder().encode(text)

function subtleCrypto(): SubtleCrypto {
  const subtle = globalThis.crypto?.subtle
  if (!subtle) throw new Error('WebCrypto unavailable')
  return subtle
}

/** 'ABCD EFGH IJKL MNOP QRST': the first 20 base32 characters of sha256(SPKI DER), upper case. */
export function fingerprintFromDigest(digest: Uint8Array): string {
  return base32(digest).toUpperCase().slice(0, 20).match(/.{4}/g)!.join(' ')
}

export async function deviceFingerprint(spki: Uint8Array, subtle: SubtleCrypto = subtleCrypto()): Promise<string> {
  return fingerprintFromDigest(new Uint8Array(await subtle.digest('SHA-256', new Uint8Array(spki))))
}

export const enrollSigningText = (hostId: string, enrollmentId: string, nonce: string) =>
  `latch-enroll-v1\n${hostId}\n${enrollmentId}\n${nonce}`
export const renewSigningText = (hostId: string, deviceId: string, nonce: string) => `latch-renew-v1\n${hostId}\n${deviceId}\n${nonce}`

/** WebCrypto ECDSA signatures are already IEEE P1363 (r || s, 64 bytes for P-256), as the Host expects. */
export async function signText(privateKey: CryptoKey, text: string, subtle: SubtleCrypto = subtleCrypto()): Promise<string> {
  return base64url(new Uint8Array(await subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, privateKey, utf8(text))))
}

export interface DeviceKeyRecord {
  hostId: string
  /** Set once the Host accepted the enrollment; renewal needs it before any snapshot is readable. */
  deviceId?: string
  privateKey: CryptoKey
  /** base64url SPKI DER. */
  publicKeySpki: string
  createdAt: string
}

export async function generateDeviceKey(hostId: string, subtle: SubtleCrypto = subtleCrypto()): Promise<DeviceKeyRecord> {
  const pair = await subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign'])
  const spki = new Uint8Array(await subtle.exportKey('spki', pair.publicKey))
  return { hostId, privateKey: pair.privateKey, publicKeySpki: base64url(spki), createdAt: new Date().toISOString() }
}

/**
 * Everything a browser needs to hold a device key safely: WebCrypto (secure
 * contexts only), IndexedDB for the non-extractable key, and Web Locks so
 * renewals in several tabs run once.
 */
export function browserKeySupport(): boolean {
  return (
    typeof globalThis.crypto?.subtle?.generateKey === 'function'
    && typeof indexedDB !== 'undefined'
    && typeof navigator !== 'undefined'
    && typeof navigator.locks?.request === 'function'
  )
}

const DATABASE = 'latch-device'
const STORE = 'keys'

function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DATABASE, 1)
    request.onupgradeneeded = () => {
      if (!request.result.objectStoreNames.contains(STORE)) request.result.createObjectStore(STORE, { keyPath: 'hostId' })
    }
    request.onsuccess = () => {
      resolve(request.result)
    }
    request.onerror = () => {
      reject(request.error ?? new Error('IndexedDB unavailable'))
    }
    request.onblocked = () => {
      reject(new Error('IndexedDB blocked'))
    }
  })
}

async function transact<T>(mode: IDBTransactionMode, run: (store: IDBObjectStore) => IDBRequest): Promise<T> {
  const database = await openDatabase()
  try {
    return await new Promise<T>((resolve, reject) => {
      const transaction = database.transaction(STORE, mode)
      const request = run(transaction.objectStore(STORE))
      transaction.oncomplete = () => {
        resolve(request.result as T)
      }
      transaction.onerror = () => {
        reject(transaction.error ?? request.error ?? new Error('IndexedDB failed'))
      }
      transaction.onabort = () => {
        reject(transaction.error ?? new Error('IndexedDB aborted'))
      }
    })
  } finally {
    database.close()
  }
}

function isRecord(value: unknown): value is DeviceKeyRecord {
  if (typeof value !== 'object' || value === null) return false
  const item = value as Record<string, unknown>
  return (
    typeof item.hostId === 'string'
    && typeof item.publicKeySpki === 'string'
    && typeof item.createdAt === 'string'
    && typeof CryptoKey !== 'undefined'
    && item.privateKey instanceof CryptoKey
    && (item.deviceId === undefined || typeof item.deviceId === 'string')
  )
}

export async function loadDeviceKey(hostId: string): Promise<DeviceKeyRecord | undefined> {
  const value = await transact<unknown>('readonly', store => store.get(hostId))
  return isRecord(value) ? value : undefined
}

/** A re-enrollment replaces the previous key for the same Host. */
export async function saveDeviceKey(record: DeviceKeyRecord): Promise<void> {
  await transact('readwrite', store => store.put(record))
}
